func parse(s string) (n int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("parse: %v", r)
		}
	}()
	arr := []int{1, 2, 3}
	idx, _ := strconv.Atoi(s)
	return arr[idx], nil
}

