func syncFile(f *os.File) error {
	if err := f.Sync(); err != nil {
		log.Printf("sync failed: %v", err)
	}
	return nil
}

func saveOverwrite(f *file) (err error) {
	defer func() { err = f.Close() }()
	return f.Write("data")
}
